class Obj:
    lib = b"spec-tg-dev"
    name = "spec"
    signature = [(None, 3, None, None), (None, 1, None, None), (None, 2, None, None)]


def call(runs):
    seen = {}

    def execute(dev, plan, bufs):
        seen["plan"], seen["bufs"] = plan.name, {k: b.name for k, b in bufs.items()}
        return runs

    class Plan:
        name, out_slot = "the plan", 1

    class Buf:
        forms = {}
        def __init__(self, name):
            self.name = name

    S.PLANS[Obj.lib] = Plan()
    keep = R.execute
    R.execute = execute
    try:
        p = KD.KTPUProgram(TinyDevice["KTPU"], Obj)
        seconds = p(Buf("a"), Buf("b"), Buf("c"))
    finally:
        R.execute = keep
        S.PLANS.pop(Obj.lib)
    return seen, seconds, p.dev.last_runs
def facts():
    _, seconds, last = call([D.Run("a", 300, 0.0), D.Run("b", 600, 0.0)])
    return {"ns": round(seconds * 1e9, 6), "last": [r.name for r in last]}
